using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-report");

        var storage = DiskBasedReportingStorage.CreateAsync(path).GetAwaiter().GetResult();

        return new ReportingConfiguration(storage);
    }

    [TestMethod]
    public async Task Chat_responds_relevantly()
    {
        // Arrange
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_relevantly));

        var chatClient = scenario.ChatConfiguration?.ChatClient
            ?? throw new InvalidOperationException("ChatClient not configured in scenario.");

        var evaluators = new IEvaluator[]
        {
            new RelevancyEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        // Act
        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Assess
        var result = await scenario.EvaluateAsync(messages, evaluators);
        scenario.Record(result);
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_followup()
    {
        // Arrange
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_coherently_to_followup));

        var chatClient = scenario.ChatConfiguration?.ChatClient
            ?? throw new InvalidOperationException("ChatClient not configured in scenario.");

        var evaluators = new IEvaluator[]
        {
            new RelevancyEvaluator(),
            new CoherenceEvaluator(),
        };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Tell me about renewable energy."),
        };

        // Act - first turn
        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Act - follow-up turn
        messages.Add(new ChatMessage(ChatRole.User, "What are the main challenges with solar power?"));
        response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        // Assess
        var result = await scenario.EvaluateAsync(messages, evaluators);
        scenario.Record(result);
    }
}

